import { execSync } from 'child_process';

function runCommand(cmd: string, timeoutMs: number): {
  stdout: string;
  exitCode: number;
} {
  try {
    const buf = execSync(cmd, {
      timeout: timeoutMs,
      stdio: ['pipe', 'pipe', 'pipe'],
      windowsHide: true,
    }) as Buffer;
    return { stdout: buf.toString('utf8').trimEnd(), exitCode: 0 };
  } catch (err: any) {
    if (err.killed) {
      return { stdout: '', exitCode: -1 };
    }
    return {
      stdout: (err.stdout ? Buffer.from(err.stdout).toString('utf8').trimEnd() : ''),
      exitCode: err.status ?? 1,
    };
  }
}

