type TextResult = { kind: 'text'; content: string };
type ErrorResult = { kind: 'error'; code: number; message: string };
type PendingResult = { kind: 'pending'; retryAfterMs: number };
type ApiResult = TextResult | ErrorResult | PendingResult;

// Process a batch of ApiResult items:
// - 'text' results: collect content into an array
// - 'error' results: if code >= 500, throw an Error with message
//   "server error: {message}"; if code < 500, skip silently
// - 'pending' results: collect retryAfterMs into a separate array
// Return { texts: string[], pendingDelays: number[] }
// Process items in order; throw on first server error encountered.
function processBatch(results: ApiResult[]): { texts: string[]; pendingDelays: number[] } {

golden_completion:
const texts: string[] = [];
const pendingDelays: number[] = [];
for (const r of results) {
  if (r.kind === 'text') { texts.push(r.content); }
  else if (r.kind === 'error') {
    if (r.code >= 500) throw new Error(`server error: ${r.message}`);
  } else if (r.kind === 'pending') { pendingDelays.push(r.retryAfterMs); }
}
return { texts, pendingDelays };

suffix:
