// Build a class RangeSet that uses well-known symbols:
//
// 1. Symbol.iterator: yield all integers in [start, end) — half-open range
// 2. Symbol.toPrimitive:
//    - hint 'number' → return the count of integers (end - start)
//    - hint 'string' → return "RangeSet(start..end)"
//    - hint 'default' → return the count (same as number)
// 3. Symbol.hasInstance: x instanceof RangeSet is true when x is a number
//    AND x is an integer AND x >= start AND x < end
// 4. Symbol.toStringTag: return 'RangeSet' so Object.prototype.toString
//    returns '[object RangeSet]'
// 5. The constructor takes (start: number, end: number)

golden_completion:
class RangeSet {
  readonly start: number;
  readonly end: number;

  constructor(start: number, end: number) {
    this.start = start;
    this.end = end;
  }

  *[Symbol.iterator](): Generator<number> {
    for (let i = this.start; i < this.end; i++) yield i;
  }

  [Symbol.toPrimitive](hint: string): number | string {
    if (hint === 'string') return `RangeSet(${this.start}..${this.end})`;
    return this.end - this.start;
  }

  static [Symbol.hasInstance](x: any): boolean {
    return typeof x === 'number' && Number.isInteger(x) && x >= 0;
  }

  get [Symbol.toStringTag](): string {
    return 'RangeSet';
  }
}

