import * as assert from 'assert';

// Numeric parsing library with STRICT validation
// Uses Number.isFinite (not global isFinite) and Number.isNaN (not global isNaN)
//
// KEY DIFFERENCES (from MDN):
// - global isNaN('hello') => true  (coerces string, then checks)
// - Number.isNaN('hello') => false (no coercion, 'hello' is not NaN)
// - Number.isNaN(NaN) => true
// - global isFinite('42') => true  (coerces '42' to 42, which is finite)
// - Number.isFinite('42') => false (no coercion, string is not finite)
// - Number.isFinite(42) => true

interface ParseResult {
    value: number;
    isValid: boolean;      // true only if Number.isFinite(value)
    originalType: string;  // typeof input
    parseMethod: string;   // 'int' or 'float'
}

golden_completion:
function strictParse(input: unknown, method: 'int' | 'float', radix?: number): ParseResult {
    const originalType = typeof input;
    let value: number;
    if (method === 'int') {
        value = parseInt(String(input), radix ?? 10);
    } else {
        value = parseFloat(String(input));
    }
    return {
        value,
        isValid: Number.isFinite(value),
        originalType,
        parseMethod: method
    };
}

