import * as assert from 'assert';

// TextEncoder.encodeInto() writes UTF-8 bytes into an existing Uint8Array
// Returns { read: number, written: number }
//   read = number of UTF-16 code units consumed from the string
//   written = number of UTF-8 bytes written to the buffer
//
// If the buffer is too small, it writes as many COMPLETE characters as fit
// (never writes partial multi-byte sequences)

const encoder = new TextEncoder();

// Demo: "Hello" = 5 bytes UTF-8, fits in 10-byte buffer
const buf1 = new Uint8Array(10);
const res1 = encoder.encodeInto('Hello', buf1);
assert.strictEqual(res1.read, 5);
assert.strictEqual(res1.written, 5);

// Demo: buffer too small — "Hello" needs 5 bytes, only 3 available
const buf2 = new Uint8Array(3);
const res2 = encoder.encodeInto('Hello', buf2);
assert.strictEqual(res2.read, 3);    // 3 chars consumed
assert.strictEqual(res2.written, 3); // 3 bytes written ('Hel')

// Demo: multi-byte char "€" = 3 bytes UTF-8
const buf3 = new Uint8Array(2);
const res3 = encoder.encodeInto('€', buf3);
assert.strictEqual(res3.read, 0);    // can't fit even 1 char
assert.strictEqual(res3.written, 0); // nothing written

interface EncodeChunkResult {
    chunk: Uint8Array;
    charsConsumed: number;
    bytesWritten: number;
    complete: boolean;  // true if entire string was consumed
}

golden_completion:
function encodeChunk(input: string, maxBytes: number): EncodeChunkResult {
    const buf = new Uint8Array(maxBytes);
    const { read, written } = encoder.encodeInto(input, buf);
    return {
        chunk: buf.subarray(0, written),
        charsConsumed: read!,
        bytesWritten: written!,
        complete: read === input.length,
    };
}

